"""Hand-authored source/receipt fixtures, no tokenizer/model or benchmark input."""
import copy,unittest
import e42_input_audit as A
F=A.F
class Inputs(unittest.TestCase):
 def setup_case(self):
  texts=['Alpha 3. ','Beta.'];units=[{'unit_id':0,'start':0,'end':9,'sentence':texts[0]},{'unit_id':1,'start':9,'end':14,'sentence':texts[1]}];r={'id':'unrelated-case','claim':'Synthetic claim.','evidence':units};premise='\n\n'.join(texts);features={'input_ids':[0,10,11,12,2,20,21,2],'attention_mask':[1]*8};empty={'input_ids':[0,2,20,21,2],'attention_mask':[1]*5};policy='FULL_UNTRUNCATED_PAIR_COMPLETE_CLAIM_ADD_SPECIAL_TOKENS_NO_PADDING_NO_TOKEN_TYPE_IDS';arm='tasksource_native_two_windows';audits=[]
  for i,(text,v)in enumerate([('',empty),(premise,features),(premise,features),(premise,features)]):audits.append({'case_id':r['id'],'arm':arm,'ordinal':i+1,'premise_sha256':A.digest(text),'claim_sha256':A.digest(r['claim']),'features':v,'joint_tokens':len(v['input_ids']),'features_sha256':A.digest(v),'tokenization_policy':policy})
  source=[{'unit_id':i,'start':u['start'],'end':u['end'],'sha256':A.digest(u['sentence'])}for i,u in enumerate(units)];common={'selected_unit_ids':[0,1],'source_spans':source,'premise_sha256':A.digest(premise),'joint_tokens':8,'packing_features_sha256':A.digest(features),'source_character_coverage':1.,'source_units_total':2,'selected_source_units':2,'selection_is_not_a_proof_of_absence':True,'premise_truncated':False,'span_splits':0,'coverage_audit':A.coverage(units,[0,1])};w0=dict(common,window_index=0,accepted_anchor_ids=[0],duplicate_first_window=False,selection_receipts=[{'anchor':0,'status':'WHOLE_GROUP_ACCEPTED','group_unit_ids':[0,1],'proposed_joint_tokens':8},{'anchor':1,'status':'GROUP_ALREADY_REPRESENTED'}]);w1=dict(common,window_index=1,accepted_anchor_ids=[],duplicate_first_window=True,selection_receipts=[{'anchor':0,'status':'ANCHOR_ALREADY_REPRESENTED_IN_FIRST'},{'anchor':1,'status':'ANCHOR_ALREADY_REPRESENTED_IN_FIRST'}]);public={'windows':[w0,w1],'packing_pair_tokenizer_calls':4,'duplicate_window_count':1,'union_selected_unit_ids':[0,1],'union_coverage_audit':A.coverage(units,[0,1]),'packing_seconds':.001};return r,arm,audits,public,features,premise
 def test_hand_written_two_unit_packing_and_duplicate_receipt(self):
  r,a,rows,p,_,_=self.setup_case();self.assertEqual(A.validate_packing_journal(rows)['records'],4);end,v=A.replay_packing(r,a,[0,1],p,rows,0);self.assertEqual(end,4);self.assertEqual(v['duplicate_window_count'],1);self.assertEqual(v['union_coverage_audit']['numeric_literal_retained'],1)
 def test_missing_lookup_or_inconsistent_repeat_fails_no_fallback(self):
  r,a,rows,p,_,_=self.setup_case()
  with self.assertRaises(ValueError):A.replay_packing(r,a,[0,1],p,rows[:-1],0)
  rows[3]['features']={'input_ids':[0,90,91,92,2,20,21,2],'attention_mask':[1]*8};rows[3]['features_sha256']=A.digest(rows[3]['features'])
  with self.assertRaisesRegex(ValueError,'REPEATED_SAME_PAIR'):A.validate_packing_journal(rows)
 def test_real_input_receipt_shape_requires_full_untruncated_claim(self):
  r,arm,rows,p,v,premise=self.setup_case();seq=[None,0,0,0,None,1,1,None];off=[[0,0],[0,5],[6,8],[11,16],[0,0],[0,9],[10,16],[0,0]];audit={'full_premise_sha256':A.digest(premise),'claim_sha256':A.digest(r['claim']),'ordered_unit_ids':[0,1],'full_joint_tokens':8,'joint_tokens':8,'full_premise_tokens':3,'consumed_premise_tokens':3,'full_claim_tokens':2,'consumed_claim_tokens':2,'claim_complete':True,'premise_truncated':False,'full_input_features_sha256':A.digest(v),'consumed_input_features_sha256':A.digest(v),'consumed_premise_tokens_sha256':A.digest([10,11,12]),'consumed_claim_tokens_sha256':A.digest([20,21]),'full_numeric_literal_count':1,'retained_numeric_literal_count':1,'omitted_numeric_literal_count':0,'numeric_literal_coverage':1.};read={'readout_id':'unrelated::window:0','raw_native_logits':[1.,0.,-1.],'input_audit':audit};saved={'readout_id':read['readout_id'],'model_tag':'tasksource','raw_native_logits':read['raw_native_logits'],'premise':premise,'claim':r['claim'],'features':v,'full_features':v,'sequence_ids':seq,'full_sequence_ids':seq,'offset_mapping':off,'full_offsets':off,'input_audit':audit};self.assertEqual(A.saved_window(r,p['windows'][0],read,saved),audit);bad=copy.deepcopy(saved);bad['features']['input_ids'][5]=99
  with self.assertRaises(ValueError):A.saved_window(r,p['windows'][0],read,bad)
if __name__=='__main__':unittest.main()
